INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('7463da7a-f2bf-58f9-a736-3e303ee8c87f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 9, 9, 'An α-particle (charge +2e) moves at 3.0 × 10⁶ m s⁻¹ at right angles to a field of 0.50 T. Calculate the magnetic force on it, in units of 10⁻¹³ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4.8', '10⁻¹³ N', false, NULL, false, NULL, 'F = BQv = 0.50 × 2 × 1.60 × 10⁻¹⁹ × 3.0 × 10⁶ = 4.80 × 10⁻¹³ N. Mark scheme (2 marks). C1: F = BQv with Q = 2e. A1: F = 4.8 × 10⁻¹³ N.', 2, NULL, NULL),
('d07d0cd3-d372-5fb3-b5d8-3dca6507936a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 10, 10, 'When Fleming''s left-hand rule is used for a moving positive charge, which way does the second finger point?', NULL, 1, 'multiple_choice'::answer_type, 'Along the velocity of the charge', NULL, false, NULL, false, NULL, 'A moving positive charge is a conventional current in its direction of motion. Mark scheme (1 mark). B1: C (Along the velocity of the charge).', 1, NULL, NULL),
('041fa607-15b1-5f81-a323-55a34a2012a6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 11, 11, 'For an electron beam, in which direction should the "current" finger of the left-hand rule point?', NULL, 1, 'multiple_choice'::answer_type, 'Opposite to the electron''s velocity', NULL, false, NULL, false, NULL, 'Conventional current is opposite to the flow of negative charge. Mark scheme (1 mark). B1: A (Opposite to the electron''s velocity).', 1, NULL, NULL),
('9524f422-4099-5e91-afba-643eeadf4c48', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 12, 12, 'A proton moves at 4.0 × 10⁵ m s⁻¹ at 60° to a magnetic field of 0.25 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.386', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = BQv sin θ = 0.25 × 1.60 × 10⁻¹⁹ × 4.0 × 10⁵ × sin 60° = 1.39 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: F = BQv sin θ. A1: F = 1.39 × 10⁻¹⁴ N.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fgb4d43efa-t fgb4d43efa-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb4d43efa-t">Proton at an angle to the field</title><desc id="fgb4d43efa-d">Horizontal field lines of flux density 0.25 T across the page; a proton moves at 4.0 × 10⁵ m s⁻¹ in a direction at 60° to the field lines.</desc><line x1="20" y1="30" x2="315.1" y2="30" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,30 313.7,33 313.7,27" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="70" x2="315.1" y2="70" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,70 313.7,73 313.7,67" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="315.1" y2="110" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,110 313.7,113 313.7,107" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="150" x2="315.1" y2="150" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,150 313.7,153 313.7,147" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="190" x2="315.1" y2="190" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,190 313.7,193 313.7,187" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="318" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">B = 0.25 T</text><circle cx="110" cy="150" r="9" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="110" cy="150" r="2.4" style="fill:currentColor;stroke:none"/><line x1="115.5" y1="140.5" x2="171.8" y2="42.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="175,37.4 174.2,46.4 167.6,42.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="28.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v = 4.0 × 10⁵ m s⁻¹</text><line x1="110" y1="150" x2="200" y2="150" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><path d="M160,150 A50,50 0 0,0 135,106.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="165.4" y="118" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">60°</text><text x="94" y="132" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">proton</text></svg>', 'Horizontal field lines of flux density 0.25 T across the page; a proton moves at 4.0 × 10⁵ m s⁻¹ in a direction at 60° to the field lines.'),
('a53c77bc-a009-5b27-8b68-2466bd3469f6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 13, 13, 'In F = BQv sin θ, what does θ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The angle between the velocity of the charge and the magnetic field', NULL, false, NULL, false, NULL, 'Only the velocity component at right angles to B contributes. Mark scheme (1 mark). B1: D (The angle between the velocity of the charge and the magnetic field).', 1, NULL, NULL),
('d776c4b1-5d02-5ad1-ae65-8a916f8b3eaa', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 14, 14, 'An electron moving at right angles to a 0.50 T field experiences a magnetic force of 6.4 × 10⁻¹⁴ N. Calculate its speed. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8e5', 'm s⁻¹', false, NULL, false, NULL, 'v = F/(BQ) = 6.4 × 10⁻¹⁴ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 8.0 × 10⁵ m s⁻¹. Mark scheme (2 marks). C1: v = F/(BQ). A1: v = 8.0 × 10⁵ m s⁻¹.', 2, NULL, NULL),
('3f2dd8ff-c66a-5571-84a7-b7fb54adc6ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 15, 15, 'What magnetic force acts on a charged particle that is at rest in a magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'None', NULL, false, NULL, false, NULL, 'F = BQv, and with v = 0 the magnetic force is zero. Mark scheme (1 mark). B1: B (None).', 1, NULL, NULL),
('5f518ed8-07cb-5cbf-ab77-d1e90be657d9', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 16, 16, 'A proton moving at 1.0 × 10⁶ m s⁻¹ at right angles to a magnetic field experiences a force of 3.2 × 10⁻¹⁴ N. Calculate the flux density. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.2', 'T', false, NULL, false, NULL, 'B = F/(Qv) = 3.2 × 10⁻¹⁴ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁶) = 0.20 T. Mark scheme (2 marks). C1: B = F/(Qv). A1: B = 0.20 T.', 2, NULL, NULL),
('fdc5216c-2541-5516-8455-4b0878d80919', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 17, 17, 'The speed of a charged particle moving at right angles to a magnetic field doubles. What happens to the magnetic force on it?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'F = BQv, so with B and Q fixed the force is proportional to the speed. Mark scheme (1 mark). B1: C (It doubles).', 1, NULL, NULL),
('31e34274-0732-5a8e-88ec-519965c94f1f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 18, 18, 'What magnetic force, in units of 10⁻¹⁴ N, acts on a doubly charged ion crossing a 1.0 T field at right angles with speed 2.0 × 10⁵ m s⁻¹? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '6.4', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = BQv = 1.0 × 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = 6.40 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: Q = 2e. A1: F = 6.4 × 10⁻¹⁴ N.', 2, NULL, NULL),
('c36692c9-7708-5219-b16f-bae650ab1594', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 19, 19, 'A charged particle moves through a uniform magnetic field and no other force acts. What happens to its kinetic energy?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'The force is always perpendicular to the motion, so no work is done. Mark scheme (1 mark). B1: A (It stays the same).', 1, NULL, NULL),
('c470a062-405d-5510-8763-812f7eda4dcc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 20, 20, 'A charged particle feels a magnetic force of 2.0 × 10⁻¹⁴ N when moving at right angles to a field. What force does it feel, in units of 10⁻¹⁴ N, moving at the same speed at 30° to the field?', NULL, 1, 'numeric'::answer_type, '1', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = 2.0 × 10⁻¹⁴ × sin 30° = 1.0 × 10⁻¹⁴ N. Mark scheme (1 mark). A1: F = 1.0 × 10⁻¹⁴ N.', 1, NULL, NULL),
('b6f065b8-c222-5883-8dbd-19e662e95b6a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 21, 21, 'A proton moves due east through a magnetic field that points vertically upwards. In which direction is the force on it?', NULL, 1, 'multiple_choice'::answer_type, 'Due south', NULL, false, NULL, false, NULL, 'Left-hand rule: first finger up, second finger east (positive charge), thumb points south. Mark scheme (1 mark). B1: D (Due south).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 230" role="img" aria-labelledby="fg32d94638-t fg32d94638-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg32d94638-t">Proton in a vertical field</title><desc id="fg32d94638-d">Top view with north up the page: a proton moving due east (to the right) through a uniform magnetic field pointing vertically upwards, out of the page.</desc><circle cx="46.2" cy="36.6" r="4.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46.2" cy="36.6" r="1.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><circle cx="46.2" cy="69.8" r="4.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46.2" cy="69.8" r="1.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><circle cx="46.2" cy="103" r="4.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46.2" cy="103" r="1.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><circle cx="46.2" cy="136.2" r="4.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="46.2" cy="136.2" r="1.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><circle cx="46.2" cy="169.4