b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="269.8" y1="140.2" x2="277.8" y2="132.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="269.8" y1="165.4" x2="277.8" y2="173.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="269.8" y1="173.4" x2="277.8" y2="165.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="160" cy="113" r="11" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="160" y="113.5" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><line x1="160" y1="99" x2="160" y2="39.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="160,33 163.8,41.2 156.2,41.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="168" y="21" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v</text><line x1="28" y1="60" x2="28" y2="32.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="28,28 31,34.3 25,34.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="28" y="19" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text><line x1="26" y1="212" x2="34" y2="220" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="220" x2="34" y2="212" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="42" y="216" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B downwards (into the page)</text></svg>', 'Top view with north up the page: an electron moving due north through a uniform magnetic field pointing vertically downwards, into the page.'),
('59e18f08-fb11-52d7-8ff6-8ba15b44cffc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 42, 42, 'A copper wire of cross-sectional area 1.0 × 10⁻⁶ m² carries 5.0 A. Copper has 8.5 × 10²⁸ free electrons per m³. The wire lies at right angles to a field of 0.20 T. (a) Calculate the drift speed of the electrons. (b) Calculate the magnetic force on one electron, in units of 10⁻²³ N. (c) Show that the total force on all the free electrons in 0.10 m of wire equals BIL. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.176', '10⁻²³ N', false, NULL, false, NULL, '(a) v = I/(nAe) = 5.0 ÷ (8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 1.60 × 10⁻¹⁹) = 3.68 × 10⁻⁴ m s⁻¹. (b) F = Bev = 0.20 × 1.60 × 10⁻¹⁹ × 3.676 × 10⁻⁴ = 1.18 × 10⁻²³ N. (c) Number of electrons = nAL = 8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 0.10 = 8.5 × 10²¹; total = 8.5 × 10²¹ × 1.176 × 10⁻²³ = 0.10 N, and BIL = 0.20 × 5.0 × 0.10 = 0.10 N. Mark scheme (6 marks). C1: v = I/(nAe). C1: F = Bev. C1: number of electrons nAL. M1: total force. B1: equals BIL. A1: F = 1.18 × 10⁻²³ N.', 6, NULL, NULL),
('3489a9b0-f103-5e2c-a8d5-608b1da8077c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 43, 43, 'A proton in the solar wind moves at 4.0 × 10⁵ m s⁻¹ at right angles to the Earth''s field, which is 3.0 × 10⁻⁵ T at that height. (a) Calculate the magnetic force on the proton. (b) Calculate its acceleration. (c) Explain why its speed does not change. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '1.15e9', 'm s⁻²', false, NULL, false, NULL, '(a) F = BQv = 3.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 4.0 × 10⁵ = 1.92 × 10⁻¹⁸ N. (b) a = 1.920 × 10⁻¹⁸ ÷ 1.67 × 10⁻²⁷ = 1.15 × 10⁹ m s⁻². (c) The force is always at right angles to the velocity, so it changes only the direction of motion. Mark scheme (5 marks). C1: F = BQv. C1: a = F/m. C1: substitution. B1: perpendicular force, no work. A1: a = 1.15 × 10⁹ m s⁻².', 5, NULL, NULL),
('b2ddcedd-bdea-5dfc-a5f0-8e4ee1a826ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 44, 44, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at 30° to a uniform field of 5.0 mT. (a) Calculate the components of its velocity parallel and perpendicular to the field. (b) Calculate the radius of its helical path, using r = mv⊥/eB. (c) Calculate the time for one revolution, T = 2πm/eB. (d) Calculate the pitch of the helix (the distance moved along the field in one revolution), in cm. Give only the answer to (d). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '1.239 cm', 'cm', false, NULL, false, NULL, '(a) v∥ = 2.0 × 10⁶ × cos 30° = 1.73 × 10⁶ m s⁻¹; v⊥ = 2.0 × 10⁶ × sin 30° = 1.0 × 10⁶ m s⁻¹. (b) r = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻³) = 0.00114 m. (c) T = 2π × 9.11 × 10⁻³¹ ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻³) = 7.15 × 10⁻⁹ s. (d) Pitch = v∥T = 1.732 × 10⁶ × 7.155 × 10⁻⁹ = 0.0124 m. In cm: 0.01239 × 100 = 1.24. Mark scheme (6 marks). C1: velocity components. C1: radius. C1: period. M1: pitch = v∥T. C1: conversion. A1: pitch = 1.24 cm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fg3e1ada42-t fg3e1ada42-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3e1ada42-t">Electron at an angle to the field</title><desc id="fg3e1ada42-d">Horizontal field lines of flux density 5.0 mT; an electron moves at 2.0 × 10⁶ m s⁻¹ at 30° to the field lines.</desc><line x1="20" y1="30" x2="315.1" y2="30" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,30 313.7,33 313.7,27" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="70" x2="315.1" y2="70" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,70 313.7,73 313.7,67" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="315.1" y2="110" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,110 313.7,113 313.7,107" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="150" x2="315.1" y2="150" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,150 313.7,153 313.7,147" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="190" x2="315.1" y2="190" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,190 313.7,193 313.7,187" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="318" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">B = 5.0 mT</text><circle cx="110" cy="150" r="9" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="110" cy="150" r="2.4" style="fill:currentColor;stroke:none"/><line x1="119.5" y1="144.5" x2="217.1" y2="88.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="222.6,85 217.4,92.4 213.6,85.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="231.2" y="90" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v = 2.0 × 10⁶ m s⁻¹</text><line x1="110" y1="150" x2="200" y2="150" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><path d="M160,150 A50,50 0 0,0 153.3,125" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.8" y="133.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">30°</text><text x="94" y="132" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">electron</text></svg>', 'Horizontal field lines of flux density 5.0 mT; an electron moves at 2.0 × 10⁶ m s⁻¹ at 30° to the field lines.'),
('b6cd3e0a-fb68-563b-938a-82c7be34f95e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 45, 45, 'Sea water flows at 2.0 m s⁻¹ along a horizontal channel 0.20 m wide, at right angles to a vertical field of 0.50 T. (a) Explain why positive and negative ions are pushed to opposite sides of the channel. (b) Calculate the magnetic force on an ion of charge e. (c) The separation continues until the electric field across the channel is vB. Calculate the p.d. across the channel. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.2', 'V', false, NULL, false, NULL, '(a) F = BQv: ions of opposite sign moving the same way feel opposite forces. (b) F = 0.50 × 1.60 × 10⁻¹⁹ × 2.0 = 1.60 × 10⁻¹⁹ N. (c) E = vB = 2.0 × 0.50 = 1.0 V m⁻¹, so V = Ed = 1.0 × 0.20 = 0.20 V. Mark scheme (5 marks). B1: opposite charges, opposite forces. C1: F = BQv. M1: E = vB at equilibrium. C1: V = Ed. A1: V = 0.20 V.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 256" role="img" aria-labelledby="fge94aa356-t fge94aa356-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge94aa356-t">Sea water in a field</title><desc id="fge94aa356-d">Top view of a horizontal channel 0.20 m wide in which sea water flows at 2.0 m s⁻¹, at right angles to a vertical 0.50 T field (into the page). A voltmeter is connected across the width of the channel.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">flow 2.0 m s⁻¹</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><polygon points="92,80 95,86.3 89,86.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="92" y1="84.9" x2="92" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="92,170 89,163.7 95,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="86" y="125" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.20 m</text><line x1="20" y1="232" x2="28" y2="240" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="240" x2="28" y2="232" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.50 T (vertical)</text></svg>', 'Top view of a horizontal channel 0.20 m wide in which sea water flows at 2.0 m s⁻¹, at right angles to a vertical 0.50 T field (into the page). A voltmeter is connected across the width of the channel.'),
('7a33672a-bd6b-525b-9c7b-ed79ef1c9f19', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 46, 46, 'An ion of charge 3e moves at right angles to a field of 0.25 T and experiences a force of 1.2 × 10⁻¹³ N. (a) Calculate its speed. (b) Its mass is 6.6 × 10⁻²⁶ kg. Calculate its kinetic energy. (c) Explain why this kinetic energy stays constant in the field. Give only the answer to (a). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1e6', 'm s⁻¹', false, NULL, false, NULL, '(a) v = F/(BQ) = 1.2 × 10⁻¹³ ÷ (0.25 × 3 × 1.60 × 10⁻¹⁹) = 1.00 × 10⁶ m s⁻¹. (b) E_k = 0.5 × 6.6 × 10⁻²⁶ × (1.000 × 10⁶)² = 3.30 × 10⁻¹⁴ J. (c) The magnetic force does no work because it is perpendicular to the velocity. Mark scheme (5 marks). C1: Q = 3e. C1: v = F/(BQ). C1: ½mv². B1: no work done. A1: v = 1.00 × 10⁶ m s⁻¹.', 5, NULL, NULL),
('3a66684a-698f-5dab-9615-3fa306284695', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'ca14c791-7996-5cb6-9fb9-b8764146fc83', 'a-level', '25.1', '9702 coursebook 25.1 · Force on a moving charge', 47, 47, 'The magnetic force on electrons of fixed speed in a 0.10 T field is measured for different angles θ between their velocity and the field: θ/° = 0, 30, 60, 90 and F/10⁻¹⁴ N = 0, 2.4, 4.2, 4.8. (a) Show that F ∝ sin θ. (b) Use the reading at 90° to find the speed of the electrons. (c) Predict the force at 45°, in units of 10⁻¹⁴ N. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '3e6', 'm s⁻¹', false, NULL, false, NULL, '(a) F/sin θ = 2.4 ÷ 0.50 = 4.8, 4.2 ÷ 0.866 = 4.85 and 4.8 ÷ 1 = 4.8 (×10⁻¹⁴ N): constant. (b) v = F/(Be) = 4.8 × 10⁻¹⁴ ÷ (0.10 × 1.60 × 10⁻¹⁹) = 3.0 × 10⁶ m s⁻¹. (c) F = 4.8 × 10⁻¹⁴ × sin 45° = 3.39 × 10⁻¹⁴ N. Mark scheme (6 marks). C1: F/sin θ values. B1: constant. C1: v = F/(Be). C1: substitution. C1: prediction. A1: v = 3.0 × 10⁶ m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fgfd28da9d-t fgfd28da9d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfd28da9d-t">Force against angle</title><desc id="fgfd28da9d-d">Table and graph of the magnetic force F (in units of 10⁻¹⁴ N) against the angle θ between velocity and field: θ = 0, 30, 60, 90° give F = 0, 2.4, 4.2, 4.8, plotted as points.</desc><g transform="translate(0,0)"><rect x="123.6" y="8" width="152.7" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="123.6" y="8" width="152.7" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="152.3" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor