('f6b0fab5-1e36-5322-bcc1-dbb9ea59a9f7', '47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', 'A parabola', 'C', false, 2),
('0c27e41d-9ee7-5cf8-8773-150604b36e04', '47964ae1-f4e8-53eb-9fb8-f0b1b58a5c73', 'A helix (spiral) along the field lines', 'D', true, 3),
('a1115fc5-8c00-5b2c-8698-8197d8452bc1', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'The Earth''s field repels particles from the equator', 'A', false, 0),
('3105c753-9a3f-51fd-9369-acf71cbaf17c', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'Charged particles from the Sun spiral along the field lines, which converge and enter the atmosphere near the poles', 'B', true, 1),
('ede35452-bd36-52c5-8b55-ee724fc5538e', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'The poles are colder, so the air glows', 'C', false, 2),
('41c552e0-5bef-545e-998e-df6c7dcc1eaa', '7698bd80-6cf0-53b7-a8cc-c3df7125bc26', 'Neutral particles are attracted to the poles', 'D', false, 3),
('914025cc-d97f-5594-a42c-deaab1f501c6', '84434522-a263-52ec-ab93-25679563cf49', 'It doubles', 'A', false, 0),
('bb4ba48c-9f80-5079-a990-bb3b89887251', '84434522-a263-52ec-ab93-25679563cf49', 'It halves', 'B', false, 1),
('f8063668-600c-5949-85d1-8f9581c8107f', '84434522-a263-52ec-ab93-25679563cf49', 'It stays the same', 'C', true, 2),
('4f751446-2504-5fe2-8cbd-3686cf074bd6', '84434522-a263-52ec-ab93-25679563cf49', 'It quadruples', 'D', false, 3),
('0cc42ac1-665d-50c9-89bc-59c96190befb', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of neutrons', 'A', true, 0),
('a02ca1bd-a599-5b61-99cb-d4b71166f27a', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of protons', 'B', false, 1),
('16a7939b-301b-5ee5-94f0-26503864ca7f', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of electrons', 'C', false, 2),
('e1210971-65fa-5bd7-b664-a481a1c755fd', '75ba8a70-dccc-5693-95c0-03fa8d5f21c1', 'A beam of α-particles', 'D', false, 3),
('53b95b51-409d-58fe-b947-cb198081c7d7', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Due west', 'A', false, 0),
('ec776a9f-679c-531d-813e-c81bb8b1641a', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Due south', 'B', false, 1),
('9316bdc4-5ae7-55de-983f-b9004bdef674', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Vertically upwards', 'C', false, 2),
('40c2f773-ff86-5ab1-b0d3-6063607e5764', '59d18be4-82d4-55b6-8a2b-11f625f248f4', 'Due east', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('58efb69e-fe52-59ba-8087-c064249f02f2', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 7, 7, 'A proton moves at 1.0 × 10⁶ m s⁻¹ at right angles to a field of 0.50 T. Calculate the radius of its circular path, in cm, using r = mv/BQ. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '2.088 cm', 'cm', false, NULL, false, NULL, 'r = mv/BQ = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 0.0209 m. In cm: 0.02088 × 100 = 2.09. Mark scheme (2 marks). C1: r = mv/BQ. A1: r = 2.09 cm.', 2, NULL, NULL),
('92193abf-512c-5ad8-b6fd-cca4734fe48e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 8, 8, 'How is the equation r = mv/BQ for a charged particle in a magnetic field obtained?', NULL, 1, 'multiple_choice'::answer_type, 'By equating the magnetic force BQv to the centripetal force mv²/r', NULL, false, NULL, false, NULL, 'BQv = mv²/r gives r = mv/BQ. Mark scheme (1 mark). B1: C (By equating the magnetic force BQv to the centripetal force mv²/r).', 1, NULL, NULL),
('b6cbeceb-a11e-53d4-ba3b-624a96d0a5bc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 9, 9, 'An α-particle (mass 6.64 × 10⁻²⁷ kg, charge 2e) moves at 2.0 × 10⁶ m s⁻¹ at right angles to a 1.0 T field. Calculate the radius of its path. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.0415', 'm', false, NULL, false, NULL, 'r = mv/BQ = 6.64 × 10⁻²⁷ × 2.0 × 10⁶ ÷ (1.0 × 2 × 1.60 × 10⁻¹⁹) = 0.0415 m. Mark scheme (2 marks). C1: Q = 2e in r = mv/BQ. A1: r = 0.0415 m.', 2, NULL, NULL),
('aab60ce3-8526-5108-96d0-ea8a5d86e6ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 10, 10, 'The flux density acting on a circling charged particle is doubled. What happens to the radius of its path?', NULL, 1, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'r = mv/BQ, so r ∝ 1/B. Mark scheme (1 mark). B1: A (It halves).', 1, NULL, NULL),
('deb15167-54cb-562d-b689-2895774ec82d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 11, 11, 'A proton moves in a circle of radius 0.10 m in a field of 0.20 T. Calculate its momentum, in units of 10⁻²¹ kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.2', '10⁻²¹ kg m s⁻¹', false, NULL, false, NULL, 'p = mv = BQr = 0.20 × 1.60 × 10⁻¹⁹ × 0.10 = 3.20 × 10⁻²¹ kg m s⁻¹. Mark scheme (2 marks). C1: p = BQr. A1: p = 3.2 × 10⁻²¹ kg m s⁻¹.', 2, NULL, NULL),
('2e43f98b-90d1-5209-a7f1-54f0d22509a6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 12, 12, 'How does the time for one orbit of a charged particle in a uniform field depend on its speed?', NULL, 1, 'multiple_choice'::answer_type, 'It does not depend on the speed', NULL, false, NULL, false, NULL, 'T = 2πm/BQ: faster particles move in larger circles, taking the same time. Mark scheme (1 mark). B1: D (It does not depend on the speed).', 1, NULL, NULL),
('33e5f99a-5ecd-558f-996b-4c9290bb1cc4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 13, 13, 'Calculate the period of a proton circling in a 1.0 T field, in ns, using T = 2πm/BQ. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '65.58 ns', 'ns', false, NULL, false, NULL, 'T = 2π × 1.67 × 10⁻²⁷ ÷ (1.0 × 1.60 × 10⁻¹⁹) = 6.56 × 10⁻⁸ s. In ns: 6.558 × 10⁻⁸ × 10⁹ = 65.6. Mark scheme (2 marks). C1: T = 2πm/BQ. A1: T = 65.6 ns.', 2, NULL, NULL),
('32f8c1c7-65d9-5615-9b36-e04483e9ccaa', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 14, 14, 'Two particles with the same charge and speed enter the same magnetic field. Particle X has the larger mass. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'X moves in the larger circle', NULL, false, NULL, false, NULL, 'r = mv/BQ, so with v, B and Q the same the radius is proportional to the mass. Mark scheme (1 mark). B1: B (X moves in the larger circle).', 1, NULL, NULL),
('6ef9828a-65e0-5128-9069-9a55a9db4ab1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 15, 15, 'An electron moves in a circle of radius 2.0 cm in a field of 1.0 mT. Calculate its speed. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '3.513e6', 'm s⁻¹', false, NULL, false, NULL, 'v = BQr/m = 1.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 0.020 ÷ 9.11 × 10⁻³¹ = 3.51 × 10⁶ m s⁻¹. Mark scheme (2 marks). C1: v = BQr/m. A1: v = 3.51 × 10⁶ m s⁻¹.', 2, NULL, NULL),
('39b97671-9cee-54c9-bab0-0e7a444444ba', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 16, 16, 'A proton and an electron move in the same magnetic field. How do their senses of rotation compare?', NULL, 1, 'multiple_choice'::answer_type, 'They circle in opposite senses', NULL, false, NULL, false, NULL, 'Opposite charges feel opposite forces for the same velocity. Mark scheme (1 mark). B1: C (They circle in opposite senses).', 1, NULL, NULL),
('d3f9c863-b4dd-5d55-aef6-8fa3edff2335', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 17, 17, 'Calculate the frequency at which an electron circles in a field of 0.10 T, in GHz, using f = BQ/2πm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '2.795 GHz', 'GHz', false, NULL, false, NULL, 'f = 0.10 × 1.60 × 10⁻¹⁹ ÷ (2π × 9.11 × 10⁻³¹) = 2.80 × 10⁹ Hz. In GHz: 2.795 × 10⁹ ÷ 10⁹ = 2.80. Mark scheme (2 marks). C1: f = BQ/2πm. A1: f = 2.80 GHz.', 2, NULL, NULL),
('983efff5-dffc-5861-a8af-3922b16a9463', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 18, 18, 'What provides the centripetal force on a charged particle moving in a circle in a uniform magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'The magnetic force on the moving charge', NULL, false, NULL, false, NULL, 'BQv acts towards the centre of the circle. Mark scheme (1 mark). B1: A (The magnetic force on the moving charge).', 1, NULL, NULL),
('bf55395f-ec2c-5cf6-8ebd-a46b0efd7579', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 19, 19, 'Calculate the flux density needed to make a proton moving at 5.0 × 10⁶ m s⁻¹ follow a circle of radius 0.50 m. Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.1044', 'T', false, NULL, false, NULL, 'B = mv/(Qr) = 1.67 × 10⁻²⁷ × 5.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 0.50) = 0.104 T. Mark scheme (2 marks). C1: rearranged r = mv/BQ. A1: B = 0.104 T.', 2, NULL, NULL),
('43334808-c2f0-5671-9e62-df523a304690', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 20, 20, 'The speed of a charged particle circling in a uniform magnetic field doubles. What happens to the radius?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'r = mv/BQ, so the radius is proportional to the speed and doubles with it. Mark scheme (1 mark). B1: D (It doubles).', 1, NULL, NULL),
('32dc79c9-da09-581b-b639-ce1f19bd75fe', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 21, 21, 'Calculate the angular speed of a proton circling in a 0.50 T field, using ω = BQ/m. Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '4.79e7', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 0.50 × 1.60 × 10⁻¹⁹ ÷ 1.67 × 10⁻²⁷ = 4.79 × 10⁷ rad s⁻¹. Mark scheme (1 mark). A1: ω = 4.79 × 10⁷ rad s⁻¹.', 1, NULL, NULL),
('d24e42c2-bfa0-5a89-ba7d-bbb7096a198d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 22, 22, 'What happens to the kinetic energy of a charged particle as it circles in a uniform magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'It stays constant', NULL, false, NULL, false, NULL, 'The magnetic force does no work. Mark scheme (1 mark). B1: B (It stays constant).', 1, NULL, NULL),
('8b4107fb-44e4-5532-b2f8-b7d4a0ea4397', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 23, 23, 'A singly charged ion of mass 3.8 × 10⁻²⁶ kg moves at 1.0 × 10⁵ m s⁻¹ at right angles to a field of 0.25 T. Calculate the radius of its path. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.095', 'm', false, NULL, false, NULL, 'r = mv/BQ = 3.8 × 10⁻²⁶ × 1.0 × 10⁵ ÷ (0.25 × 1.60 × 10⁻¹⁹) = 0.0950 m. Mark scheme (2 marks). C1: r = mv/BQ. A1: r = 0.0950 m.', 2, NULL, NULL),
('c25b9857-7a5f-5cd1-bd63-33e4ef2599ec', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '9a577035-5226-4d06-b1f8-39a2b1f93b0a', 'a-level', '25.2', '9702 coursebook 25.2 · Orbiting charged particles', 24, 24, 'Electrons accelerated from rest through 200 V enter a field of 1.0 mT at right angles. Calculate the radius of their path, in cm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '4.772 cm', 'cm', false, NULL, false, NULL, 'v = √(2 × 1.60 × 10⁻¹⁹ × 200 ÷ 9.11 × 10⁻³¹) = 8.38 × 10⁶ m s⁻¹. r = 9.11 × 10⁻³¹ × 8.382 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁻³) = 0.0477 m. In cm: 0.04772 × 100 = 4.77. Mark scheme (3 marks). C1: speed from eV = ½mv². C1: r = mv/BQ. A1: r = 4.77 cm.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 260" role="img" aria-labelledby="fgef896a84-t fgef896a84-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgef896a84-t">Electron beam bent into a circle</title><desc id="fgef896a84-d">Electrons accelerated through 200 V leave an electron gun and move in a circle in a uniform 1.0 mT field directed into the page.</desc><line x1="30" y1="27.5" x2="38" y2="35.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="35.5" x2="38" y2="27.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="62.5" x2="38" y2="70.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="70.5" x2="38" y2="62.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="97.5" x2="38" y2="105.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="105.5" x2="38" y2="97.5" st