('7dcd64c0-8d66-57f2-8498-c13b3ef6182b', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating BQv to mg', 'A', false, 0),
('97810554-032f-5e60-bdd4-9a2c4f2b8807', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating BQv to ½mv²', 'B', false, 1),
('9cee4a17-1e5a-5518-8d3f-046a97e83e2e', '92193abf-512c-5ad8-b6fd-cca4734fe48e', 'By equating the magnetic force BQv to the centripetal force mv²/r', 'C', true, 2),
