('a64a0596-2c51-5daf-b92f-b6d5d00d489e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 9, 9, 'Two parallel plates 5.0 mm apart have a p.d. of 300 V. Calculate the electric field between them.', NULL, 1, 'numeric'::answer_type, '60000', 'V m⁻¹', false, NULL, false, NULL, 'E = V/d = 300 ÷ 5.0 × 10⁻³ = 6.0 × 10⁴ V m⁻¹. Mark scheme (2 marks). C1: E = V/d. A1: E = 6.0 × 10⁴ V m⁻¹.', 2, NULL, NULL),
('e8105bb7-a289-58da-b3cb-79aeae02221f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 10, 10, 'How are the electric field, the magnetic field and the particle velocity arranged in a velocity selector?', NULL, 1, 'multiple_choice'::answer_type, 'All three are mutually at right angles', NULL, false, NULL, false, NULL, 'Only then can the two forces be equal and opposite and both perpendicular to v. Mark scheme (1 mark). B1: A (All three are mutually at right angles).', 1, NULL, NULL),
