('e0f650c3-f06f-56d6-aec9-e360b09db399', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 17, 17, 'Calculate the p.d. needed across plates 8.0 mm apart so that a velocity selector with B = 0.040 T selects ions of speed 5.0 × 10⁵ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '160', 'V', false, NULL, false, NULL, 'E = Bv = 0.040 × 5.0 × 10⁵ = 2.0 × 10⁴ V m⁻¹. V = Ed = 2.0 × 10⁴ × 8.0 × 10⁻³ = 160 V. Mark scheme (2 marks). C1: E = Bv then V = Ed. A1: V = 160 V.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 222" role="img" aria-labelledby="fgdff6708c-t fgdff6708c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgdff6708c-t">Velocity selector</title><desc id="fgdff6708c-d">A velocity selector with plates 8.0 mm apart and a magnetic field of 0.040 T into the page, selecting ions of speed 5.0 × 10⁵ m s⁻¹.</desc><rect x="120" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="120" y="160" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="108" y="164" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><line x1="139.3" y1="68.3" x2="147.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="76.3" x2="147.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1=