('c8d85595-6cd6-560a-b3dc-be36a269e831', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 34, 34, 'Calculate the magnetic flux density needed to cancel the deflection of an electron moving at 1.0 × 10⁷ m s⁻¹ through an electric field of 2.0 × 10³ V m⁻¹, in µT.', NULL, 2, 'numeric'::answer_type, '200 uT', 'µT', false, NULL, false, NULL, 'B = E/v = 2.0 × 10³ ÷ 1.0 × 10⁷ = 2.0 × 10⁻⁴ T. In µT: 2.0 × 10⁻⁴ × 10⁶ = 200. Mark scheme (3 marks). C1: B = E/v. C1: conversion. A1: B = 200 µT.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 242" role="img" aria-labelledby="fgf6ad24e8-t fgf6ad24e8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf6ad24e8-t">Cancelling the deflection</title><desc id="fgf6ad24e8-d">An electron moving at 1.0 × 10⁷ m s⁻¹ between plates giving an electric field of 2.0 × 10³ V m⁻¹; a magnetic field B between the plates cancels the deflection.</desc><rect x="120" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="120" y="160" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="108" y="164" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><line x1="139.3" y1="68.3" x2="147.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="76.3" x2="147.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;str