196 96.3,193 96.3,199" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="196" x2="305.1" y2="196" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="310,196 303.7,199 303.7,193" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="200" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 cm</text><text x="200" y="20" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 1.2 × 10⁴ V m⁻¹</text><line x1="20" y1="110" x2="79.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,110 77.8,113.8 77.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="22" y="96" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.4 × 10⁷ m s⁻¹</text><polyline points="90,110 97.3,110 104.7,109.8 112,109.6 119.3,109.3 126.7,108.8 134,108.3 141.3,107.7 148.7,107 156,106.2 163.3,105.3 170.7,104.4 178,103.3 185.3,102.1 192.7,100.9 200,99.5 207.3,98.1 214.7,96.5 222,94.9 229.3,93.2 236.7,91.3 244,89.4 251.3,87.4 258.7,85.3 266,83.1 273.3,80.8 280.7,78.5 288,76 295.3,73.4 302.7,70.8 310,68" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/></svg>', 'Electrons moving at 2.4 × 10⁷ m s⁻¹ enter midway between plates 5.0 cm long with a field of 1.2 × 10⁴ V m⁻¹ and are deflected towards the positive plate.'),
('ae385b5f-5009-5b5a-864c-518e0131599e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 47, 47, 'Free electrons drift at 1.0 × 10⁻⁴ m s⁻¹ along a metal strip 1.0 cm wide, at right angles to a field of 0.50 T. They are pushed sideways until the electric field across the strip balances the magnetic force. (a) Calculate the electric field needed for balance. (b) Calculate the p.d. across the strip, in µV. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.5 uV', 'µV', false, NULL, false, NULL, '(a) eE = Bev, so E = vB = 1.0 × 10⁻⁴ × 0.50 = 5.0 × 10⁻⁵ V m⁻¹. (b) V = Ed = 5.0 × 10⁻⁵ × 0.010 = 5.0 × 10⁻⁷ V. In µV: 5.0 × 10⁻⁷ × 10⁶ = 0.50. Mark scheme (5 marks). M1: eE = Bev. C1: E = vB. C1: V = Ed. C1: conversion. A1: V = 0.50 µV.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 276" role="img" aria-labelledby="fg7cb00307-t fg7cb00307-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7cb00307-t">Metal strip in a field</title><desc id="fg7cb00307-d">Top view of a metal strip 1.0 cm wide carrying a current along its length, at right angles to a 0.50 T field into the page; the free electrons drift at 1.0 × 10⁻⁴ m s⁻¹ and a voltage develops across the width.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><polygon points="92,80 95,86.3 89,86.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="92" y1="84.9" x2="92" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="92,170 89,163.7 95,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="86" y="125" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0 cm</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">electron drift speed 1.0 × 10⁻⁴ m s⁻¹</text><line x1="20" y1="252" x2="28" y2="260" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="260" x2="28" y2="252" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.50 T</text></svg>', 'Top view of a metal strip 1.0 cm wide carrying a current along its length, at right angles to a 0.50 T field into the page; the free electrons drift at 1.0 × 10⁻⁴ m s⁻¹ and a voltage develops across the width.'),
('2c2c0c4d-95bf-59df-8a6b-c43d8f562ad3', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 48, 48, 'For a beam of fixed speed, the electric field needed to cancel the magnetic deflection is measured for several magnetic fields: B/mT = 0.50, 1.0, 1.5, 2.0 and E/10⁴ V m⁻¹ = 1.0, 2.0, 3.0, 4.0. The particles are electrons. (a) Explain why the graph of E against B is a straight line through the origin. (b) Calculate the speed of the electrons. (c) Calculate their kinetic energy, in eV. Give only the answer to (b). Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '2e7', 'm s⁻¹', false, NULL, false, NULL, '(a) E = vB with v constant. (b) v = gradient = 4.0 × 10⁴ ÷ 2.0 × 10⁻³ = 2.0 × 10⁷ m s⁻¹. (c) E_k = 0.5 × 9.11 × 10⁻³¹ × (2.0 × 10⁷)² ÷ 1.60 × 10⁻¹⁹ = 1140 eV. Mark scheme (6 marks). B1: E = vB. M1: gradient = v. C1: v. C1: ½mv². C1: in eV. A1: v = 2.0 × 10⁷ m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fg6b6b7f21-t fg6b6b7f21-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6b6b7f21-t">Balancing field against flux density</title><desc id="fg6b6b7f21-d">Table and graph of the electric field needed to cancel the magnetic deflection against flux density: B = 0.50, 1.0, 1.5, 2.0 mT need E = 1.0, 2.0, 3.0, 4.0 × 10⁴ V m⁻¹, a straight line through the origin.</desc><g transform="translate(0,0)"><rect x="108.9" y="8" width="182.1" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="108.9" y="8" width="182.1" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="144.2" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B / mT</text><text x="235.3" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">E / 10⁴ V m⁻¹</text><line x1="179.6" y1="8" x2="179.6" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="108.9" y1="36" x2="291.1" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="144.2" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.50</text><text x="235.3" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="108.9" y1="64" x2="291.1" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="144.2" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="235.3" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="108.9" y1="92" x2="291.1" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="144.2" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.5</text><text x="235.3" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0</text><line x1="108.9" y1="120" x2="291.1" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="144.2" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><text x="235.3" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0</text></g><g transform="translate(0,160)"><line x1="24" y1="34" x2