oke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="105.4" y1="202" x2="105.4" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="105.4" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="186.7" y1="202" x2="186.7" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="186.7" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="268.1" y1="202" x2="268.1" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="268.1" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="349.5" y1="202" x2="349.5" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="349.5" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="20" y1="202" x2="24" y2="202" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="202" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="164.7" x2="24" y2="164.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="164.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1</text><line x1="20" y1="127.3" x2="24" y2="127.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="127.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="90" x2="24" y2="90" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="90" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3</text><line x1="20" y1="52.7" x2="24" y2="52.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="52.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><text x="203" y="234" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">B / mT</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E / 10⁴ V m⁻¹</text><line x1="101.4" y1="160.7" x2="109.4" y2="168.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="101.4" y1="168.7" x2="109.4" y2="160.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182.7" y1="123.3" x2="190.7" y2="131.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182.7" y1="131.3" x2="190.7" y2="123.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="264.1" y1="86" x2="272.1" y2="94" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="264.1" y1="94" x2="272.1" y2="86" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="345.5" y1="48.7" x2="353.5" y2="56.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="345.5" y1="56.7" x2="353.5" y2="48.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'Table and graph of the electric field needed to cancel the magnetic deflection against flux density: B = 0.50, 1.0, 1.5, 2.0 mT need E = 1.0, 2.0, 3.0, 4.0 × 10⁴ V m⁻¹, a straight line through the origin.'),
('28b652fe-ba6f-58d4-99ee-c0d59c3705a4', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 49, 49, 'A velocity selector is to select α-particles of kinetic energy 5.0 MeV (1 MeV = 1.6 × 10⁻¹³ J; mass 6.64 × 10⁻²⁷ kg) using B = 0.50 T. (a) Calculate their speed. (b) Calculate the electric field needed. (c) Comment on the p.d. needed across plates 1.0 cm apart. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '7.762e6', 'V m⁻¹', false, NULL, false, NULL, '(a) v = √(2E_k/m) = √(2 × 5.0 × 1.6 × 10⁻¹³ ÷ 6.64 × 10⁻²⁷) = 1.55 × 10⁷ m s⁻¹. (b) E = Bv = 0.50 × 1.552 × 10⁷ = 7.76 × 10⁶ V m⁻¹. (c) V = Ed ≈ 7.76 × 10⁴ V: very large, so sparking would be a problem. Mark scheme (5 marks). C1: speed. C1: E = Bv. C1: value. B1: impractically large p.d. A1: E = 7.76 × 10⁶ V m⁻¹.', 5, NULL, NULL),
('4f156a89-bdcc-5f97-8a23-ae68898be2d1', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '939a9c6c-194e-484e-83e2-0ab494ffa0d4', 'a-level', '25.3', '9702 coursebook 25.3 · Electric and magnetic fields', 50, 50, 'Deuterons (mass 3.34 × 10⁻²⁷ kg, charge e) are selected by crossed fields with E = 3.0 × 10⁴ V m⁻¹ and B = 0.10 T. They then move against an electric field until they stop. (a) Calculate their speed. (b) Calculate their kinetic energy. (c) Calculate the stopping p.d. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '939.4', 'V', false, NULL, false, NULL, '(a) v = 3.0 × 10⁴ ÷ 0.10 = 3.0 × 10⁵ m s⁻¹. (b) E_k = 0.5 × 3.34 × 10⁻²⁷ × (3.0 × 10⁵)² = 1.50 × 10⁻¹⁶ J. (c) eV = E_k, so V = 1.503 × 10⁻¹⁶ ÷ 1.60 × 10⁻¹⁹ = 939 V. Mark scheme (6 marks). C1: v = E/B. C1: ½mv². M1: eV = E_k. C1: value. B1: units consistent. A1: V = 939 V.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('69049f82-0ed6-5eaf-9947-1e7bc91f4af4', 'e7c8682c-445a-556f-a6bf-5b99f62e125f', 'The electric force is zero', 'A', false, 0),
('9e03d6c8-6c9b-5a19-a290-048f0bf6b65c', 'e7c8682c-445a-556f-a6bf-5b99f62e125f', 'The magnetic force is zero', 'B', false, 1),
('d13befdb-f3c6-5d8c-b7c6-55ab9c31ab9a', 'e7c8682c-445a-556f-a6bf-5b99f62e125f', 'The electric force EQ equals the magnetic force BQv and acts in the opposite direction', 'C', true, 2),
('2fe19b9e-b369-5c95-a14f-fabcb361dace', 'e7c8682c-445a-556f-a6bf-5b99f62e125f', 'The particle''s weight balances the magnetic force', 'D', false, 3),
('b89deb0b-e3c8-5b1e-9246-ada6572e2b09', 'e8105bb7-a289-58da-b3cb-79aeae02221f', 'All three are mutually at right angles', 'A', true, 0),
('d5527f59-e77c-50c4-9016-9024ae1f037f', 'e8105bb7-a289-58da-b3cb-79aeae02221f', 'All three are parallel', 'B', false, 1),
('1d1762a4-35d8-5ae6-9af1-56b9c993f67f', 'e8105bb7-a289-58da-b3cb-79aeae02221f', 'E and B are parallel; v is at right angles to both', 'C', false, 2),
('7f0d799a-1bfb-5dec-b539-a2cb1e86d858', 'e8105bb7-a289-58da-b3cb-79aeae02221f', 'v and B are parallel; E is at right angles', 'D', false, 3),
('3b2be9ba-3fb4-5595-bb41-5ba53311e88b', 'e3aa2736-1e28-503e-a50d-710e3819396a', 'In the direction of the magnetic force', 'A', false, 0),
('ab1e37d0-55d7-5110-8822-b0ce6ada67dc', 'e3aa2736-1e28-503e-a50d-710e3819396a', 'They are not deflected', 'B', false, 1),
('afdf62c1-1999-51fb-bb3a-8e3ecd821811', 'e3aa2736-1e28-503e-a50d-710e3819396a', 'Along the magnetic field', 'C', false, 2),
('6c947d03-5064-5351-a29a-23f0266e6599', 'e3aa2736-1e28-503e-a50d-710e3819396a', 'In the direction of the electric force', 'D', true, 3),
('b3c9379b-a279-5d65-89d2-7aecaa47b206', '3e54ab45-e4b1-5165-a6b4-93c141f90b84', 'It doubles', 'A', false, 0),
('640b2086-0326-57ee-96e2-7fe761921fee', '3e54ab45-e4b1-5165-a6b4-93c141f90b84', 'It stays the same', 'B', true, 1),
('98c00b04-ebc0-5377-b055-532115d26bb4', '3e54ab45-e4b1-5165-a6b4-93c141f90b84', 'It halves', 'C', false, 2),
('b9d2e891-74a4-5205-bda1-15e6d4407d91', '3e54ab45-e4b1-5165-a6b4-93c141f90b84', 'No particles can pass', 'D', false, 3),
('d418ebc6-c2cd-5452-9ed3-57e9ce5d8ff3', '2798c098-e838-5aa5-9615-1bdfaf7ea255', 'They are deflected towards the positive plate', 'A', false, 0),
('edbe61a9-5c59-5b27-b237-54299f5bb4fe', '2798c098-e838-5aa5-9615-1bdfaf7ea255', 'They are deflected along the magnetic field', 'B', false, 1),
('6e14413a-4147-52cf-a77b-c895790cee2d', '2798c098-e838-5aa5-9615-1bdfaf7ea255', 'They also pass through undeflected', 'C', true, 2),
('e2f63674-908e-552e-8ca7-4169aa6a6866', '2798c098-e838-5aa5-9615-1bdfaf7ea255', 'They are stopped', 'D', false, 3),
('c5beca03-e279-5c9d-8bc9-ac8c4fbe5e53', '6b31872c-00bc-5336-b19c-ab1fe9f1ac18', 'The electric force', 'A', true, 0),
('09de5dbe-ad19-55f6-97fa-29f609cae42f', '6b31872c-00bc-5336-b19c-ab1fe9f1ac18', 'The magnetic force', 'B', false, 1),
('6ba8c877-79ed-5b44-81fd-e09ef4405256', '6b31872c-00bc-5336-b19c-ab1fe9f1ac18', 'Both forces', 'C', false, 2),
('0b385d6f-2b07-5aaa-a389-b4123e846899', '6b31872c-00bc-5336-b19c-ab1fe9f1ac18', 'Neither force', 'D', false, 3),
('42ed42c5-c161-50c2-af6a-cd39fceed71d', '07d5a649-b1ac-56a4-83f7-43227625ac77', 'Both are proportional to speed', 'A', false, 0),
('00cf6d30-d1ed-5af2-8170-2dce38cbf932', '07d5a649-b1ac-56a4-83f7-43227625ac77', 'Neither depends on speed', 'B', false, 1),
('5c261763-3dfe-595d-b8b8-1fbf719d28a0', '07d5a649-b1ac-56a4-83f7-43227625ac77', 'The electric force is proportional to speed; the magnetic force does not depend on speed', 'C', false, 2),
('b083b81a-17c6-5cbb-a183-5a361c3f898d', '07d5a649-b1ac-56a4-83f7-43227625ac77', 'The electric force does not depend on speed; the magnetic force is proportional to speed', 'D', true, 3),
